maxred_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Max-reduction over the middle dimension of a contiguous 3D tensor [B, R, N].
// Output shape: [B, N]. Optimization: persistent grid-stride loop -- the
// grid is sized to exactly one full wave (SMs x max blocks/SM from the
// occupancy API), eliminating the partial tail wave flagged by Nsight
// (est. 25% of runtime). Each thread still owns one output column with
// the full reduction over R kept inside the thread and eight independent
// accumulators hiding the load latency. Consecutive threads map to
// consecutive columns in every grid-stride iteration, so each warp load
// still reads one full 128-byte contiguous cache line. No shared memory,
// no warp shuffles and no __syncthreads are needed.
template <typename T>
__global__ void max_reduce_middle_kernel(const T* __restrict__ X,
                                         T* __restrict__ Y,
                                         int B, int R, int N)
{
  const T neg_inf = -std::numeric_limits<T>::infinity();
  const int64_t total = (int64_t)B * N;
  const int64_t gstride = (int64_t)gridDim.x * blockDim.x;
  for (int64_t g = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
       g < total; g += gstride) {
    const int b = (int)(g / N);
    const int col = (int)(g - (int64_t)b * N);
    const int64_t base = (int64_t)b * R * N + col;
    const T* __restrict__ p = X + base;
    const int64_t step = (int64_t)N;
    T acc0 = neg_inf, acc1 = neg_inf, acc2 = neg_inf, acc3 = neg_inf;
    T acc4 = neg_inf, acc5 = neg_inf, acc6 = neg_inf, acc7 = neg_inf;
    int r = 0;
    for (; r + 7 < R; r += 8) {
      acc0 = ::max(acc0, __ldg(p));
      acc1 = ::max(acc1, __ldg(p + step));
      acc2 = ::max(acc2, __ldg(p + 2 * step));
      acc3 = ::max(acc3, __ldg(p + 3 * step));
      acc4 = ::max(acc4, __ldg(p + 4 * step));
      acc5 = ::max(acc5, __ldg(p + 5 * step));
      acc6 = ::max(acc6, __ldg(p + 6 * step));
      acc7 = ::max(acc7, __ldg(p + 7 * step));
      p += 8 * step;
    }
    for (; r < R; ++r) {
      acc0 = ::max(acc0, __ldg(p));
      p += step;
    }
    acc0 = ::max(acc0, acc1);
    acc2 = ::max(acc2, acc3);
    acc4 = ::max(acc4, acc5);
    acc6 = ::max(acc6, acc7);
    acc0 = ::max(acc0, acc2);
    acc4 = ::max(acc4, acc6);
    const T res = ::max(acc0, acc4);
    Tensor mY = make_tensor(make_gmem_ptr(Y + (int64_t)b * N),
                            make_shape(N),
                            make_stride(Int<1>{}));
    mY(col) = res;
  }
}
__device__ __forceinline__ void atomicMaxFloat(float* addr, float val) {
  int* ai = reinterpret_cast<int*>(addr);
  int old = *ai;
  int assumed;
  do {
    assumed = old;
    if (__int_as_float(assumed) >= val) return;
    old = atomicCAS(ai, assumed, __float_as_int(val));
  } while (assumed != old);
}
// Vectorized fast path (optimization: float4 vectorized global loads).
// Each block sweeps a contiguous chunk of rows of one batch slab [R, N]
// linearly in memory: 16-byte aligned float4 loads, fully coalesced and
// sequential at the DRAM level. Column maxima are accumulated in shared
// memory (bank-conflict-free since consecutive threads touch consecutive
// columns), and partials across row-chunks are combined with atomicMax.
// Valid whenever every slab start is 16-byte aligned: (R * N) % 4 == 0
// (rows_per_chunk is a multiple of 4 so every chunk start stays aligned).
template <typename T>
__global__ void max_reduce_slab_vec_kernel(const T* __restrict__ X,
                                           T* __restrict__ Y,
                                           int64_t R, int64_t N,
                                           int64_t rows_per_chunk)
{
  extern __shared__ T smem[];
  const T neg_inf = -std::numeric_limits<T>::infinity();
  Tensor sS = make_tensor(make_smem_ptr(smem),
                          make_shape(N),
                          make_stride(Int<1>{}));
  for (int64_t i = threadIdx.x; i < N; i += blockDim.x) {
    sS(i) = neg_inf;
  }
  __syncthreads();
  const int64_t b = blockIdx.y;
  const int64_t r0 = (int64_t)blockIdx.x * rows_per_chunk;
  int64_t r1 = r0 + rows_per_chunk;
  if (r1 > R) r1 = R;
  const int64_t e0 = b * R * N + r0 * N;
  const int64_t L = (r1 - r0) * N;
  const int64_t F = L >> 2;
  const int rem = (int)(L & 3LL);
  const float4* __restrict__ base4 = reinterpret_cast<const float4*>(X + e0);
  const int64_t stride4 = blockDim.x;
  const int64_t step_mod = (stride4 * 4) % N;
  int64_t col = ((int64_t)threadIdx.x * 4) % N;
  for (int64_t idx = threadIdx.x; idx < F; idx += stride4) {
    const float4 v = __ldg(base4 + idx);
    if (col + 3 < N) {
      sS(col)     = ::max(sS(col),     v.x);
      sS(col + 1) = ::max(sS(col + 1), v.y);
      sS(col + 2) = ::max(sS(col + 2), v.z);
      sS(col + 3) = ::max(sS(col + 3), v.w);
    } else {
      int64_t c = col;
      sS(c) = ::max(sS(c), v.x);
      c = (c + 1 == N) ? 0 : c + 1;
      sS(c) = ::max(sS(c), v.y);
      c = (c + 1 == N) ? 0 : c + 1;
      sS(c) = ::max(sS(c), v.z);
      c = (c + 1 == N) ? 0 : c + 1;
      sS(c) = ::max(sS(c), v.w);
    }
    col += step_mod;
    if (col >= N) col -= N;
  }
  if (threadIdx.x < rem) {
    const int64_t pos = (F << 2) + threadIdx.x;
    const int64_t c = pos % N;
    sS(c) = ::max(sS(c), __ldg(X + e0 + pos));
  }
  __syncthreads();
  T* __restrict__ yrow = Y + b * N;
  for (int64_t i = threadIdx.x; i < N; i += blockDim.x) {
    atomicMaxFloat(yrow + i, sS(i));
  }
}
torch::Tensor max_reduce_dim(torch::Tensor x, int64_t dim) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(x.dim() == 3, "x must be 3D [B, R, N]");
  if (dim < 0) dim += x.dim();
  TORCH_CHECK(dim == 1, "custom kernel currently reduces over dim == 1");
  auto x_c = x.contiguous();
  const int64_t B = x_c.size(0);
  const int64_t R = x_c.size(1);
  const int64_t N = x_c.size(2);
  constexpr int Threads = 256;
  dim3 block(Threads);
  const int64_t work_items = B * N;
  if (work_items == 0) {
    return torch::empty({B, N}, x_c.options());
  }
  int dev = 0;
  cudaGetDevice(&dev);
  int sms = 0;
  cudaDeviceGetAttribute(&sms, cudaDevAttrMultiProcessorCount, dev);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  // Dispatch to the vectorized float4 kernel when each batch slab starts
  // on a 16-byte boundary and the shared-memory column table fits.
  int max_smem = 0;
  cudaDeviceGetAttribute(&max_smem, cudaDevAttrMaxSharedMemoryPerBlockOptin, dev);
  const int64_t smem_bytes = N * (int64_t)sizeof(float);
  const bool vec_ok = ((R * N) % 4 == 0) && (B <= 65535) &&
                      (smem_bytes <= (int64_t)max_smem);
  if (vec_ok) {
    auto yv = torch::full(
        {B, N}, -std::numeric_limits<float>::infinity(), x_c.options());
    if (smem_bytes > 48 * 1024) {
      cudaFuncSetAttribute(max_reduce_slab_vec_kernel<float>,
                           cudaFuncAttributeMaxDynamicSharedMemorySize,
                           (int)smem_bytes);
    }
    const int64_t target_blocks = (int64_t)sms * 32;
    int64_t chunks = (target_blocks + B - 1) / B;
    if (chunks < 1) {
      chunks = 1;
    }
    int64_t rows_per_chunk = (R + chunks - 1) / chunks;
    rows_per_chunk = (rows_per_chunk + 3) & ~(int64_t)3;
    if (rows_per_chunk < 4) {
      rows_per_chunk = 4;
    }
    chunks = (R + rows_per_chunk - 1) / rows_per_chunk;
    TORCH_CHECK(chunks <= 0x7fffffff, "invalid grid size");
    dim3 grid_vec((unsigned)chunks, (unsigned)B);
    max_reduce_slab_vec_kernel<float><<<grid_vec, block, smem_bytes, stream>>>(
        x_c.data_ptr<float>(),
        yv.data_ptr<float>(),
        R, N, rows_per_chunk);
    auto errv = cudaGetLastError();
    TORCH_CHECK(errv == cudaSuccess, "max_reduce_slab_vec_kernel launch failed: ",
                cudaGetErrorString(errv));
    return yv;
  }
  auto y = torch::empty({B, N}, x_c.options());
  const int64_t needed_blocks = (work_items + Threads - 1) / Threads;
  int blocks_per_sm = 0;
  cudaOccupancyMaxActiveBlocksPerMultiprocessor(
      &blocks_per_sm, max_reduce_middle_kernel<float>, Threads, 0);
  if (blocks_per_sm < 1) {
    blocks_per_sm = 1;
  }
  const int64_t wave_blocks = (int64_t)sms * blocks_per_sm;
  const int64_t blocks =
      needed_blocks < wave_blocks ? needed_blocks : wave_blocks;
  TORCH_CHECK(blocks <= 0x7fffffff, "invalid grid size");
  dim3 grid((unsigned)blocks, 1);
  max_reduce_middle_kernel<float><<<grid, block, 0, stream>>>(
      x_c.data_ptr<float>(),
      y.data_ptr<float>(),
      (int)B, (int)R, (int)N);
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "max_reduce_middle_kernel launch failed: ",
              cudaGetErrorString(err));
  return y;
}
